<?php
require_once 'config/database.php';require_once 'includes/auth.php';require_once 'includes/functions.php';require_login();$uid=current_user()['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$sid=(int)$_POST['session_id'];$status=$_POST['status'];if(in_array($status,['completed','cancelled'],true)){$s=$pdo->prepare("UPDATE LearningSessions SET status=? WHERE session_id=? AND (teacher_id=? OR learner_id=?)");$s->execute([$status,$sid,$uid,$uid]);if($status==='completed')award_if_missing($pdo,$uid,'First Swap','Completed a learning session.','★','milestone');flash('success','Session updated.');}redirect('sessions.php');}
$s=$pdo->prepare("SELECT ls.*,s.skill_name,t.first_name tf,t.last_name tl,l.first_name lf,l.last_name ll FROM LearningSessions ls JOIN Skills s ON s.skill_id=ls.skill_id JOIN Users t ON t.user_id=ls.teacher_id JOIN Users l ON l.user_id=ls.learner_id WHERE ls.teacher_id=? OR ls.learner_id=? ORDER BY ls.session_date DESC,ls.start_time DESC");$s->execute([$uid,$uid]);$rows=$s->fetchAll();$title='Sessions';include 'includes/header.php';
?>
<div class="page-head"><div><div class="eyebrow">LEARNING SESSIONS</div><h1>Learn together.</h1></div><a class="btn" href="schedule-session.php">+ Schedule</a></div><div class="grid cards-2"><?php foreach($rows as $r):?><div class="card session"><div class="request-head"><span class="badge <?=$r['status']?>"><?=e($r['status'])?></span><span><?=e($r['session_date'])?></span></div><h2><?=e($r['session_title'])?></h2><p><?=e($r['skill_name'])?> · <?=substr($r['start_time'],0,5)?>–<?=substr($r['end_time'],0,5)?></p><p class="muted"><?=e($r['session_description'])?></p><div class="meta">Teacher: <?=e($r['tf'].' '.$r['tl'])?> · Learner: <?=e($r['lf'].' '.$r['ll'])?></div><?php if($r['status']==='scheduled'):?><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="session_id" value="<?=$r['session_id']?>"><button class="btn" name="status" value="completed">Mark completed</button><button class="btn ghost" name="status" value="cancelled">Cancel</button></form><?php endif;?></div><?php endforeach;?></div>
<?php include 'includes/footer.php'; ?>
